import {createGame,CATALOG,BY_ID,REGIONS,ELEMENTS,GENERATES,CONTROLS,SLOT_SYMBOLS,RATES,SUMMON_COST,LOGIN_REWARDS} from './engine.js';
import {RARITIES} from './data.js';
const game=createGame(),$=(s,r=document)=>r.querySelector(s),icon=(n)=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`,fmt=n=>Number(n).toLocaleString('ja-JP');
let page='home',banner='sakura',region='meadow',floor=1,rarity='ALL',element='ALL',collectionRegion='ALL',ownedOnly=false,guardianOnly=false,bet=300,busy=false,activeModal=null,returnFocus,toastTimer,audioCtx,revealToken=0,revealTimer=null,revealData=null;
let pendingImport=null,tapCount=0,tapTimer=null;
let farmJob=null,farmTimer=null,autoBattle=false,autoTimer=null,damageDisplay=null,slotResult=null;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const reduced=()=>!game.state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
const phase=(el)=>`<span class="badge element-badge" style="--phase-color:${ELEMENTS[el].color}">${el}</span>`;
const stars=r=>`<span class="stars">${'✦'.repeat(RARITIES[r].stars)}</span>`;
const rarityStyle=u=>`--rarity:${RARITIES[u.rarity].color};--phase-color:${ELEMENTS[u.element].color}`;
const featured={meadow:['ur-01','sr-02'],sakura:['ssr-05','sr-06'],jade:['ur-05','r-09']};
function toast(msg){const target=$('#modal-feedback');if($('#modal').open&&target){target.textContent=msg;return;}$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function sound(kind='click'){if(!game.state.settings.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const now=audioCtx.currentTime,notes=kind==='ur'?[523,659,784,1047,1319,1568]:kind==='rare'?[659,784,1047,1319]:kind==='win'?[523,659,784]:kind==='lose'?[330,294]:kind==='hit'?[380,280]:[659];notes.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(f,now+i*.09);g.gain.setValueAtTime(.001,now+i*.09);g.gain.linearRampToValueAtTime(.045,now+i*.09+.01);g.gain.exponentialRampToValueAtTime(.001,now+i*.09+.26);o.connect(g);g.connect(audioCtx.destination);o.start(now+i*.09);o.stop(now+i*.09+.3);});}catch{}}
function confetti(rare=false){if(reduced())return;const c=$('#confetti'),ctx=c.getContext('2d');if(!ctx)return;const w=c.width=innerWidth,h=c.height=innerHeight;let start;const ps=Array.from({length:rare?65:28},()=>({x:w/2,y:h*.4,vx:(Math.random()-.5)*13,vy:-4-Math.random()*9,s:2+Math.random()*4,a:Math.random()*6,color:['#d2b57a','#d4a3b5','#a8bda1','#d7cba6'][Math.floor(Math.random()*4)]}));function draw(t){start??=t;ctx.clearRect(0,0,w,h);for(const p of ps){p.x+=p.vx;p.vy+=.18;p.y+=p.vy;p.a+=.03;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.globalAlpha=Math.max(0,1-(t-start)/1700);ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(0,0,p.s,p.s*.55,0,0,Math.PI*2);ctx.fill();ctx.restore();}if(t-start<1700)requestAnimationFrame(draw);else ctx.clearRect(0,0,w,h);}requestAnimationFrame(draw);}
function sync(){const s=game.state;$('#coin-balance').textContent=fmt(s.coins);$('#shard-balance').textContent=fmt(s.shards);$('#nav-count').textContent=Object.keys(s.collection).length;$('#mission-dot').hidden=!(game.missions().some(m=>!m.claimed&&m.progress>=m.target)||Math.floor(s.raids/3)>s.raidRewards);$('#save-status').hidden=game.storageAvailable;$('#save-status').textContent=game.storageAvailable?'':'この環境では保存できません';document.body.classList.toggle('motion-off',!s.settings.motion);}
function heading(title,extra=''){return `<div class="page-heading"><h1>${title}</h1>${extra?`<div class="page-extra">${extra}</div>`:''}</div>`;}
function regionTabs(current,action){return `<div class="region-tabs" aria-label="地域">${Object.values(REGIONS).map(r=>`<button class="region-tab ${current===r.id?'active':''}" style="--region-color:${r.color}" data-action="${action}" data-region="${r.id}" aria-pressed="${current===r.id}"><span class="tab-dot"></span>${r.name}</button>`).join('')}</div>`;}
function smallUnit(id){const u=BY_ID[id],o=game.state.collection[id];return `<button class="small-companion" data-action="unit" data-id="${id}" aria-label="${u.name}の詳細"><img src="${u.art}" alt=""><span>${u.name}<small>${u.element} · ${u.role} / Lv.${o?.level||1}</small></span></button>`;}
function card(u,result=null,index=0){const o=game.state.collection[u.id];return `<button class="unit-card ${!o?'locked':''}" data-action="unit" data-id="${u.id}" style="${rarityStyle(u)};--i:${index}" aria-label="${u.name} ${u.rarity} ${o?'獲得済み':'未獲得'}"><div class="unit-image-wrap"><img src="${u.art}" alt="" loading="lazy"><span class="unit-rarity">${u.rarity}</span><span class="unit-element">${u.element}</span>${result?(result.new?'<span class="new-badge">NEW</span>':`<span class="duplicate-badge">重複 +1 / 育成石 +${result.shards}</span>`):game.state.squad.includes(u.id)?'<span class="equipped">編成中</span>':''}</div><div class="unit-info"><h3>${u.name}</h3><div><span>${o?'Lv.'+o.level:u.role}</span><span class="break-dots">${o?'◆'.repeat(o.breakthrough)+'◇'.repeat(6-o.breakthrough):u.rarity}</span></div></div></button>`;}
function loginPanel(withHeading=true){const l=game.loginStatus();return `<section class="panel login-panel">${withHeading?'<div class="section-header"><h2>ログインボーナス</h2></div>':''}<div class="login-days">${LOGIN_REWARDS.map((r,i)=>`<div class="login-day ${i<l.index||!l.available&&i===l.index?'claimed':''} ${i===l.index?'today':''}"><small>${i+1}日目</small>${icon(i===6?'gem':'coin')}<strong>${fmt(r.coins)}</strong>${i<l.index||!l.available&&i===l.index?'<span>✓</span>':''}</div>`).join('')}</div><div class="daily-reward"><span>${icon('coin')} ${fmt(l.reward.coins)}<span>+</span>${icon('gem')} ${l.reward.shards}</span><button class="button gold" data-action="login" ${!l.available?'disabled':''}>${l.available?'受け取る':'本日受取済み'}</button></div><p class="page-note">毎日0時（日本時間）更新</p></section>`;}
function homePage(){
 const s=game.state,u=BY_ID[s.favorite]||BY_ID[s.squad[0]]||CATALOG[0],o=s.collection[u.id],login=game.loginStatus();
 return `<section class="home-screen" aria-label="お気に入り" style="--home-accent:${ELEMENTS[u.element].color}">
  <img class="home-scene" src="assets/scene-${u.region}.svg" alt="">
  <div class="home-top">
   <button class="home-identity" data-action="unit" data-id="${u.id}" aria-label="${u.name}の詳細">
    <span class="home-name">${u.name}${icon('chev')}</span>
    <span class="home-level"><span style="color:${RARITIES[u.rarity].color}">${u.rarity}</span>${phase(u.element)}<span>Lv.${o?.level||1}</span></span>
   </button>
   <button class="home-change" data-action="favorites" aria-label="お気に入りを変更" title="お気に入りを変更">${icon('refresh')}<span>変更</span></button>
  </div>
  <button class="home-daily" data-action="daily" aria-label="ログインボーナス${login.available?'・受取可能':''}"><span class="daily-icon">${icon('gift')}${login.available?'<i class="reward-dot"></i>':''}</span><span>ログインボーナス</span></button>
  <button class="home-character" data-action="pet" aria-label="${u.name}に触れる"><img src="${u.art}" alt="${u.name}"><span class="touch-ring"></span></button>
  <div class="character-speech" aria-live="polite" hidden></div>
  <div class="home-bottom">${s.expedition?`<span class="home-progress">${REGIONS[s.expedition.region].name} · ${s.expedition.stage}層</span>`:''}<a class="home-explore" href="#raid">${icon('swords')}<span>${s.expedition?'探索を再開':'探索に出る'}</span>${icon('arrow')}</a></div>
 </section>`;
}
function dailyBonus(){openModal(`${modalHead('ログインボーナス')}${loginPanel(false)}`,'daily');}

function favorites(){openModal(`${modalHead('お気に入りを変更')}<div class="favorite-grid">${Object.keys(game.state.collection).map(id=>{const u=BY_ID[id];return `<button class="favorite-option ${id===game.state.favorite?'selected':''}" data-action="favorite" data-id="${id}"><img src="${u.art}" alt=""><span>${u.name}</span>${id===game.state.favorite?icon('check'):''}</button>`;}).join('')}</div>`,'favorites');}
function touchFavorite(){const button=$('.home-character');if(!button)return;tapCount++;button.classList.remove('touched');void button.offsetWidth;button.classList.add('touched');const bubble=$('.character-speech'),u=BY_ID[game.state.favorite];const lines=u.role==='攻撃'?['準備できてる。','行こう。','……くすぐったい。']:u.role==='守護'?['ここにいるよ。','任せて。','そろそろ出発？']:['おかえり。','ひと休みする？','ふふ。'];bubble.textContent=lines[(tapCount-1)%lines.length];bubble.hidden=false;sound();clearTimeout(tapTimer);tapTimer=setTimeout(()=>{button.classList.remove('touched');if(bubble.isConnected)bubble.hidden=true;},1800);}
function installHelp(){openModal(`${modalHead('ホーム画面に追加')}<div class="rules-copy"><h3>iPhone・iPad</h3><p>Safariで開き、共有ボタン →「ホーム画面に追加」→「追加」を選びます。対応するiOSでは「Webアプリとして開く」をオンにしてください。</p><h3>Android・PC</h3><p>Chromeなどのブラウザメニューから「アプリをインストール」または「ホーム画面に追加」を選びます。</p><p>アイコンから起動すると専用画面で遊べます。進行状況は端末内に保存されます。引っ越し前には設定から保存データを書き出してください。</p></div>`,'install');}
function summonPage(){const s=game.state,r=REGIONS[banner],u=BY_ID[featured[banner][0]],v=BY_ID[featured[banner][1]],pool=CATALOG.filter(c=>c.region===banner),preview=[u,...pool.filter(x=>x.id!==u.id).sort((a,b)=>RARITIES[b.rarity].stars-RARITIES[a.rarity].stars)].slice(0,6);return `${heading('召喚',`<button class="text-button" data-action="rates">${icon('info')} 提供割合</button>`)}${regionTabs(banner,'banner')}<div class="summon-layout"><section class="summon-card"><div class="summon-stage"><img class="scene" src="assets/scene-${banner}.svg" alt=""><div class="banner-copy"><span class="banner-label">常設召喚</span><h2>${r.name}</h2><p class="banner-pool">${u.name}・${v.name}など<br>この地域の仲間 ${pool.length}種</p><div class="featured-name">${stars(u.rarity)}<strong>${u.name}</strong><div class="badges">${phase(u.element)}<span class="badge">${u.role}</span><span class="badge">${u.gem}</span></div></div></div><img class="banner-art small" src="${v.art}" alt="${v.name}"><img class="banner-art" src="${u.art}" alt="${u.name}"><div class="banner-details"><button class="text-button" data-action="unit" data-id="${u.id}">仲間の詳細 ${icon('chev')}</button></div></div><div class="summon-controls"><div class="pity-row"><div class="pity-item ur"><span>UR確定まで <b>あと${60-s.pity}回</b></span><div class="progress"><i style="width:${s.pity/60*100}%"></i></div></div><div class="pity-item ssr"><span>SSR以上確定まで <b>あと${20-s.highPity}回</b></span><div class="progress"><i style="width:${s.highPity/20*100}%"></i></div></div></div><div class="pull-buttons"><button class="pull-button" data-action="summon" data-count="1" ${busy?'disabled':''}>${icon('spark')}<span>1回召喚<small>${icon('coin')} 300</small></span></button><button class="pull-button multi" data-action="summon" data-count="10" ${busy?'disabled':''}><span class="pull-guarantee">${s.pity>=50?'UR確定':s.highPity>=10?'SSR以上確定':'SR以上1体確定'}</span>${icon('spark')}<span>10回召喚<small>${icon('coin')} 2,700</small></span></button></div></div></section><aside class="summon-side"><a class="panel collection-overview" href="#collection"><span class="label">図鑑 ${icon('arrow')}</span><div class="collection-number">${Object.keys(s.collection).length}<small> / ${CATALOG.length}</small></div><div class="progress"><i style="width:${Object.keys(s.collection).length/CATALOG.length*100}%"></i></div></a><div class="panel side-squad"><h3>編成</h3>${s.squad.length?s.squad.map(smallUnit).join(''):'<p class="page-note">仲間を編成してください。</p>'}<a href="#raid">探索へ ${icon('arrow')}</a></div></aside></div><div class="section-header"><h2>この地域の仲間</h2><button class="text-button" data-action="view-region" data-region="${banner}">全${pool.length}種を見る ${icon('chev')}</button></div><div class="unit-grid preview-grid">${preview.map(u=>card(u)).join('')}</div>`;}
function squadBar(){const s=game.state,info=game.teamInfo(),links=s.squad.slice(1).map((id,i)=>GENERATES[BY_ID[s.squad[i]].element]===BY_ID[id].element?`${BY_ID[s.squad[i]].element}→${BY_ID[id].element}`:null).filter(Boolean);return `<div class="panel squad-bar"><div class="squad-meta"><small>編成戦力</small><strong>${fmt(game.power())}</strong></div><div class="squad-slots">${Array.from({length:3},(_,i)=>s.squad[i]?`<div class="squad-slot">${smallUnit(s.squad[i])}<button class="move-button" data-action="move" data-id="${s.squad[i]}" aria-label="${BY_ID[s.squad[i]].name}の編成順を変える">⇄</button></div>`:'<div class="squad-slot empty">未編成</div>').join('')}</div><button class="button secondary small" data-action="equip-best">${icon('spark')} おまかせ</button></div><p class="squad-note">${info.balanced?'<b>役割連携：HP +15%</b>':'攻撃・守護・回復を1体ずつ編成するとHP +15%'}${links.length?'　/　相生：'+links.join('、'):''}</p>`;}
function collectionPage(){const s=game.state,units=[...CATALOG].sort((a,b)=>RARITIES[b.rarity].stars-RARITIES[a.rarity].stars).filter(u=>(rarity==='ALL'||u.rarity===rarity)&&(element==='ALL'||u.element===element)&&(collectionRegion==='ALL'||u.region===collectionRegion)&&(!ownedOnly||s.collection[u.id])&&(!guardianOnly||u.guardian));return `${heading('仲間',`${Object.keys(s.collection).length} / ${CATALOG.length}種類`)}${s.expedition?'<div class="notice">探索中は編成・育成を変更できません。 <a href="#raid" class="text-button">探索に戻る →</a></div>':''}${squadBar()}<div class="filters"><div class="filter-group">${['ALL','UR','SSR','SR','R'].map(r=>`<button class="filter-button ${rarity===r?'active':''}" data-action="rarity" data-value="${r}" aria-pressed="${rarity===r}">${r==='ALL'?'すべて':r}</button>`).join('')}</div><div class="filter-group"><select class="select" id="region-filter" aria-label="地域で絞り込み"><option value="ALL">全地域</option>${Object.values(REGIONS).map(r=>`<option value="${r.id}" ${collectionRegion===r.id?'selected':''}>${r.name}</option>`).join('')}</select><label class="checkbox-label"><input type="checkbox" id="owned-only" ${ownedOnly?'checked':''}>所持のみ</label></div></div><div class="filters"><div class="filter-group"><button class="filter-button ${element==='ALL'?'active':''}" data-action="element" data-value="ALL">全属性</button>${Object.keys(ELEMENTS).map(e=>`<button class="filter-button ${element===e?'active':''}" data-action="element" data-value="${e}" style="color:${ELEMENTS[e].color}">${e}</button>`).join('')}</div><label class="checkbox-label"><input type="checkbox" id="guardian-only" ${guardianOnly?'checked':''}>四神</label></div><div class="unit-grid">${units.length?units.map(u=>card(u)).join(''):'<div class="empty-state">該当する仲間はいません。</div>'}</div>`;}
function explorationPage(){const s=game.state;if(s.battle)return battlePage(s.battle);if(s.expedition)return campPage(s.expedition);const r=REGIONS[region],cleared=s.regions[region];floor=Math.min(floor,Math.min(10,cleared+1));const enemy=game.enemy(region,floor);const logs=s.history.filter(x=>x.type==='raid').slice(0,5);return `${heading('探索',`<button class="text-button" data-action="combat-help">${icon('info')} 五行と戦闘</button>`)}${regionTabs(region,'explore-region')}<div class="explore-layout"><div><section class="panel map-panel"><div class="map-scene"><img src="assets/scene-${region}.svg" alt=""><div class="map-caption"><h2>${r.name}</h2><p>${cleared} / 10層クリア</p></div></div><div class="map-floor"><div class="floor-grid">${Array.from({length:10},(_,i)=>{const n=i+1;return `<button class="floor-button ${n<=cleared?'cleared':''} ${n===floor?'selected':''}" data-action="floor" data-floor="${n}" ${n>cleared+1||farmJob?'disabled':''}>${n}層<small>${n<=cleared?'クリア':n>cleared+1?'未解放':n%5===0?'ボス':'未クリア'}</small></button>`;}).join('')}</div><div class="floor-info"><span>敵属性 ${phase(enemy.phase)} / 弱点 ${phase(enemy.weak)}</span><span>勝利 <strong>${fmt(220+floor*55+(enemy.boss?250:0))}</strong> コイン</span></div><div class="map-actions"><button class="button" data-action="start-explore" ${busy||farmJob?'disabled':''}>${icon('map')} ${floor}層から探索</button><div class="farm-controls"><select class="select" id="farm-count" aria-label="周回回数" ${farmJob?'disabled':''}><option value="1">1回</option><option value="5">5回</option><option value="10" selected>10回</option></select><button class="button secondary" data-action="farm" ${floor>cleared||busy||farmJob?'disabled':''}>${icon('refresh')} 周回</button></div></div><p class="page-note">探索は体力を引き継ぎ、休憩は2回。周回はクリア済みの階層で行えます。</p></div></section>${farmJob?farmProgress():''}<section class="panel battle-log"><h3>探索記録</h3>${logs.length?logs.map(l=>`<p><b class="${l.win?'win':'lose'}">${l.win?'勝利':'敗北'}</b>　${REGIONS[l.region]?.short||'草原'} ${l.stage}層　+${fmt(l.coins)} コイン / +${l.shards} 育成石</p>`).join(''):'<p>まだ記録がありません。</p>'}</section></div><aside class="panel explore-side"><h3>編成</h3>${s.squad.map(smallUnit).join('')}<a class="button secondary" href="#collection">編成・育成</a><p class="page-note">${game.teamInfo().balanced?'役割連携：全員のHP +15%':'攻撃・守護・回復をそろえるとHP +15%'}</p></aside></div>`;}
function farmProgress(){return `<div class="farm-progress"><div><span>周回 ${farmJob.done} / ${farmJob.total}</span><button class="text-button" data-action="stop-farm">停止 ${icon('pause')}</button></div><div class="progress"><i style="width:${farmJob.done/farmJob.total*100}%"></i></div><p>+${fmt(farmJob.coins)} コイン / +${farmJob.shards} 育成石</p></div>`;}
function battlePage(b){const s=game.state,actor=b.team[b.turn],u=actor&&BY_ID[actor.id],chain=u&&b.lastElement&&GENERATES[b.lastElement]===u.element;return `${heading('探索',`<button class="text-button" data-action="combat-help">${icon('info')} 戦闘ルール</button>`)}<section class="panel battle-panel"><div class="battle-top"><div><span>${REGIONS[b.region].name} · ${b.stage}層</span><span>ターン ${b.round}</span></div><button class="text-button" data-action="return-confirm">帰還 ${icon('arrow')}</button></div><div class="battle-arena"><img class="scene" src="assets/scene-${b.region}.svg" alt=""><div class="enemy-status"><div class="enemy-name">${b.enemy.name} ${phase(b.enemy.phase)} <span class="badge">弱点 ${b.enemy.weak}</span></div><div class="hp-bar"><i style="width:${b.enemy.hp/b.enemy.maxHp*100}%"></i></div><small>${b.enemy.hp} / ${b.enemy.maxHp} HP</small></div><img class="enemy-art" src="${BY_ID[b.enemy.art].art}" alt="${b.enemy.name}">${damageDisplay?`<div class="battle-number ${damageDisplay.skill?'skill':''}">−${damageDisplay.amount}</div>`:''}<div class="enemy-intent">${b.round%3===0?'次の敵行動：全体攻撃':'次の敵行動：単体攻撃'}</div></div><div class="allies">${b.team.map((t,i)=>{const unit=BY_ID[t.id];return `<div class="ally ${i===b.turn&&b.status==='active'?'current':''} ${t.hp<=0?'fainted':''}"><div class="ally-top"><span style="color:${ELEMENTS[unit.element].color}">${unit.element} · ${unit.role}</span>${i===b.turn&&b.status==='active'?'<span class="active-label">行動中</span>':''}</div><img src="${unit.art}" alt=""><h3>${unit.name}</h3><div class="hp-bar"><i style="width:${t.hp/t.maxHp*100}%"></i></div><div class="ally-hp"><span>${t.hp}/${t.maxHp}</span><span class="shield-label">${t.shield?'盾 '+t.shield:unit.role}</span></div></div>`;}).join('')}</div>${b.status==='active'?`<div class="battle-actions"><div class="buttons"><button class="button secondary" data-action="battle-act" data-value="attack" ${busy||autoBattle?'disabled':''}>${icon('swords')} 攻撃</button><button class="button skill" data-action="battle-act" data-value="skill" ${busy||autoBattle||actor.cooldown?'disabled':''}>${icon(u.role==='回復'?'heart':u.role==='守護'?'shield':'spark')} ${actor.cooldown?'あと'+actor.cooldown+'ターン':u.skill}</button><button class="button secondary" data-action="battle-act" data-value="guard" ${busy||autoBattle?'disabled':''}>${icon('shield')} 防御</button></div><button class="button ghost small" data-action="auto-battle">${icon(autoBattle?'pause':'play')} ${autoBattle?'自動停止':'自動戦闘'}</button><p>${u.name}：${game.skillDescription(u.id)} ${chain?'相生ボーナス +15%':''}</p></div><div class="battle-log live" aria-live="polite">${b.log.slice(-2).map(e=>`<p>${e.text}</p>`).join('')||'<p>仲間3体の行動後、敵が行動します。</p>'}</div>`:battleEnd(b)}</section>`;}
function battleEnd(b){const ex=game.state.expedition,r=b.reward;return `<div class="battle-end"><h2>${b.status==='victory'?'勝利':'探索終了'}</h2>${r.first?'<span class="badge">初回クリア +500コイン</span>':''}<div class="rewards"><span class="reward-pill">${icon('coin')} +${fmt(r.coins)}</span><span class="reward-pill stone">${icon('gem')} +${r.shards}</span></div>${ex?`<div class="camp-summary">探索中の報酬：<strong>${fmt(ex.coins)} コイン / ${ex.shards} 育成石</strong><br>帰還で全額獲得。敗北するとコインが25%減ります。<br>休憩：残り ${ex.rests} / 2回（全員のHPを40%回復）</div><div class="end-actions"><button class="button secondary" data-action="return-home">帰還して受け取る</button><button class="button" data-action="continue">${ex.stage}層へ</button><button class="button gold" data-action="rest" ${!ex.rests?'disabled':''}>休憩して進む</button></div>`:`<p>${r.banked?`受け取り：${fmt(r.banked.coins)} コイン / ${r.banked.shards} 育成石${!r.win?'（探索中コインの75%）':''}`:'報酬を受け取りました。'}</p><div class="end-actions"><button class="button" data-action="dismiss-battle">探索一覧へ</button></div>`}</div>`;}
function campPage(ex){return `${heading('探索を再開')}<section class="panel battle-end"><h2>${REGIONS[ex.region].name}</h2><p>次は${ex.stage}層 / 休憩残り ${ex.rests}回</p><div class="camp-team">${ex.team.map(t=>`<div><img src="${BY_ID[t.id].art}" alt="${BY_ID[t.id].name}"><div class="hp-bar"><i style="width:${t.hp/t.maxHp*100}%"></i></div><small>${t.hp} / ${t.maxHp}</small></div>`).join('')}</div><div class="camp-summary">探索中の報酬：${fmt(ex.coins)} コイン / ${ex.shards} 育成石<br>帰還で全額獲得。敗北するとコインが25%減ります。</div><div class="end-actions"><button class="button secondary" data-action="return-home">帰還して受け取る</button><button class="button" data-action="continue">続ける</button><button class="button gold" data-action="rest" ${!ex.rests?'disabled':''}>休憩して進む</button></div></section>`;}
function slotsPage(){const history=game.state.history.filter(h=>h.type==='slot').slice(0,5),reels=slotResult?.reels||[0,2,4];return `${heading('スロット',`<button class="text-button" data-action="slot-help">${icon('info')} 確率・払戻し</button>`)}<div class="slots-layout"><section class="panel slot-machine"><h2>宝石スロット</h2><div class="reels">${reels.map((r,i)=>`<div class="reel ${slotResult?.multiplier>1?'winner':''}" id="reel-${i}"><img src="${SLOT_SYMBOLS[r].art}" alt="${SLOT_SYMBOLS[r].name}"></div>`).join('')}</div><div class="slot-feedback" id="slot-feedback" role="status">${slotResult?slotResult.multiplier>1?`${SLOT_SYMBOLS[slotResult.reels[0]].name}が3つ！ ${slotResult.multiplier}倍`:slotResult.multiplier===1?'2つ一致 · ベットを返却':'そろいませんでした。':'3つそろうと4〜30倍。2つならベット返却。'}${slotResult?`<small>払戻し ${fmt(slotResult.payout)} / 収支 ${slotResult.net>=0?'+':''}${fmt(slotResult.net)} コイン</small>`:''}</div><div class="bet-options" aria-label="ベット額">${[100,300,1000].map(v=>`<button class="filter-button ${bet===v?'active':''}" data-action="bet" data-bet="${v}" aria-pressed="${bet===v}" ${busy?'disabled':''}>${fmt(v)} コイン</button>`).join('')}</div><button class="button spin-button" data-action="spin" ${busy?'disabled':''}>${icon('refresh')} ${busy?'回転中…':fmt(bet)+'コインで回す'}</button><p class="slot-footnote">各絵柄20%・3リール独立抽選</p></section><aside class="panel slot-paytable"><h3>3つ一致した場合</h3>${SLOT_SYMBOLS.map(s=>`<div class="pay-row"><span class="symbols">${[1,2,3].map(()=>`<img src="${s.art}" alt="${s.name}">`).join('')}</span><b>×${s.multiplier}</b></div>`).join('')}<div class="pay-row small"><span>2つ一致</span><b>×1</b></div><div class="pay-row small"><span>すべて異なる</span><b>×0</b></div><p class="page-note">倍率はベットを含む払戻し額です。<br>例：300コイン × 10倍 = 3,000コイン受取。</p></aside></div><section class="panel slot-history"><h3>直近の結果</h3>${history.length?history.map(h=>`<p><span class="symbols">${h.reels.map(i=>`<img src="${SLOT_SYMBOLS[i].art}" alt="${SLOT_SYMBOLS[i].name}">`).join('')}</span><span class="amount"><span>ベット ${fmt(h.bet)}</span><span class="${h.payout>h.bet?'win':''}">${h.payout-h.bet>=0?'+':''}${fmt(h.payout-h.bet)}</span></span></p>`).join(''):'<p>まだ結果がありません。</p>'}</section>`;}
function missionsPage(){const s=game.state,ready=Math.floor(s.raids/3)-s.raidRewards,prog=Math.min(3,s.raids-s.raidRewards*3);return `${heading('報酬')}${loginPanel()}<section class="panel repeat-reward"><div><h3>戦闘3回ごとの報酬</h3><p>300コイン + 育成石10個</p></div><span class="repeat-progress">${prog} / 3${ready>1?'（'+ready+'回分）':''}</span><button class="button secondary" data-action="raid-reward" ${!ready?'disabled':''}>受け取る</button></section><div class="mission-grid">${game.missions().map((m,i)=>`<section class="panel mission-card ${m.claimed?'claimed':''}"><div class="icon">${icon(['spark','map','book','gem','coin','star','book','map'][i])}</div><h3>${m.title}</h3><div class="mission-reward">${icon('coin')} ${fmt(m.reward)}</div><div class="mission-progress"><span>${m.claimed?'受取済み':m.progress>=m.target?'達成':'進行中'}</span><span>${m.progress} / ${m.target}</span></div><div class="progress"><i style="width:${m.progress/m.target*100}%"></i></div><button class="button ${m.progress<m.target?'secondary':''}" data-action="claim" data-id="${m.id}" ${m.claimed||m.progress<m.target?'disabled':''}>${m.claimed?'受取済み':'受け取る'}</button></section>`).join('')}</div>`;}
function render(){sync();document.body.dataset.page=page;document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=({home:homePage,summon:summonPage,collection:collectionPage,raid:explorationPage,arcade:slotsPage,missions:missionsPage}[page])();}
function navigate(){const hash=location.hash.slice(1),next=({gamble:'arcade'}[hash]||hash);page=['home','summon','collection','raid','arcade','missions'].includes(next)?next:'home';if(page!=='raid'){stopAuto();stopFarm(false);}render();window.scrollTo(0,0);}
function modalHead(title){return `<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close-modal" aria-label="閉じる">${icon('close')}</button></div>`;}
function openModal(html,type){const d=$('#modal');activeModal=type;$('#modal-content').innerHTML=`<div class="modal-inner">${html}<div id="modal-feedback" class="modal-feedback" role="status" aria-live="polite"></div></div>`;if(!d.open){returnFocus=document.activeElement;d.showModal();}d.append($('#confetti'));d.scrollTop=0;}
function closeModal(){if(activeModal==='charge'){finishReveal();return;}clearTimeout(revealTimer);$('#modal').close();activeModal=null;if(returnFocus?.isConnected)returnFocus.focus();}
function showUnit(id){const u=BY_ID[id];if(!u)return;const s=game.state,o=s.collection[id],st=game.stats(id),cost=game.levelCost(id);openModal(`${modalHead('仲間の詳細')}<div class="unit-detail"><div class="detail-portrait"><img src="${u.art}" alt="${u.name}"><span class="gem-note">${icon('gem')} ${u.gem}</span></div><div class="detail-info"><div class="badges"><span class="badge" style="color:${RARITIES[u.rarity].color}">${u.rarity}</span>${phase(u.element)}<span class="badge">${u.role}</span><span class="badge">${REGIONS[u.region].short}</span></div><h3>${u.name}</h3>${u.guardian?`<span class="badge">四神：${u.guardian}</span>`:''}<div class="detail-stats"><div><small>HP</small><strong>${st.hp}</strong></div><div><small>攻撃</small><strong>${st.attack}</strong></div><div><small>レベル</small><strong>${o?'Lv.'+o.level:'未獲得'}</strong></div></div><p class="skill-description"><strong>${u.skill}</strong>${game.skillDescription(id)}<br>再使用まで${o?.breakthrough>=6?'1':'2'}ターン。</p>${o?`<button class="button ghost" data-action="favorite" data-id="${id}">${icon('heart')} ${s.favorite===id?'ホームに表示中':'ホームに置く'}</button><button class="button secondary" data-action="level" data-id="${id}" ${o.level>=30?'disabled':''}>${icon('gem')} ${o.level>=30?'最大レベル':'育成する · '+cost+'石'}</button><div class="breakthrough-track" aria-label="${o.breakthrough}突破">${Array.from({length:6},(_,i)=>`<span class="break-step ${i<o.breakthrough?'filled':''}">${i<o.breakthrough?'✦':'◇'}</span>`).join('')}</div><button class="button gold" data-action="breakthrough" data-id="${id}" ${o.breakthrough>=6?'disabled':''}>${icon('star')} ${o.breakthrough>=6?'6突破 · 最大':'突破する · 重複1体'}</button><p class="break-detail">各突破：基礎HP・攻撃 +12%。3突破でスキル強化、6突破で再使用を1ターン短縮。</p><p class="owned-info">未使用の重複 ${game.copies(id)}体 / 育成石 ${fmt(s.shards)}</p>${s.squad.includes(id)?`<button class="button ghost" data-action="equip" data-id="${id}">編成から外す</button>`:s.squad.length<3?`<button class="button" data-action="equip" data-id="${id}">編成に入れる</button>`:`<p class="owned-info">入れ替える仲間を選択</p><div class="equip-options">${s.squad.map((x,i)=>`<button data-action="equip" data-id="${id}" data-slot="${i}"><img src="${BY_ID[x].art}" alt="">${BY_ID[x].name}</button>`).join('')}</div>`}`:`<p class="modal-subtitle">${REGIONS[u.region].name}の召喚から入手できます。</p><button class="button secondary" data-action="go-banner" data-region="${u.region}">召喚へ</button>`}</div></div>`,'unit');}
function ratesModal(){const counts=r=>CATALOG.filter(u=>u.region===banner&&u.rarity===r).length;openModal(`${modalHead('提供割合')}<p class="modal-subtitle">${REGIONS[banner].name} / 同レアリティ内は均等</p><table class="rules-table"><thead><tr><th>レアリティ</th><th>種類</th><th>通常排出率</th></tr></thead><tbody>${['UR','SSR','SR','R'].map(r=>`<tr><td>${r}</td><td>${counts(r)}種</td><td>${Math.round(RATES[r]*100)}%</td></tr>`).join('')}</tbody></table><div class="rules-copy"><p>10連でSR以上1体確定。最初の9体がすべてRで10体目もRだった場合、10体目をSRに変更します。</p><p>SSR以上が出ず19回召喚すると、次はSSR以上確定。URが出ず59回召喚すると、次はUR確定です。UR保証が優先されます。</p><p>保証カウントは全地域で共通。SSR以上の獲得でSSR保証、UR獲得でUR保証をリセットします。</p><p>重複時は同キャラの突破素材1体と育成石を獲得。育成石はR 5 / SR 15 / SSR 50 / UR 150個。最大突破後も育成石を獲得できます。</p><p>紹介されている仲間の確率上昇はありません。</p></div>`,'rates');}
function combatHelp(){openModal(`${modalHead('五行と戦闘')}<div class="rules-copy"><h3>相剋：有利な相手にダメージ +35%</h3><div class="elements-map">${['木','土','水','火','金'].map(e=>`<span><b style="--phase-color:${ELEMENTS[e].color}">${e}</b> →</span>`).join('')}<span>木</span></div><h3>相生：直前の仲間からつなぐと +15%</h3><div class="elements-map">${['木','火','土','金','水'].map(e=>`<span><b style="--phase-color:${ELEMENTS[e].color}">${e}</b> →</span>`).join('')}<span>木</span></div><p>同じターン内の直前の攻撃・スキルが自分を生む属性なら、ダメージと回復が15%増加。編成順を入れ替えて狙えます。</p><h3>役割と行動</h3><p>攻撃：高倍率の連撃。守護：全体に盾。回復：最も傷ついた仲間を回復。防御は自分に20%の盾を付け、次の敵の攻撃を半減します。</p><p>味方全員の行動後に敵が行動。3ターンごとに敵が全体攻撃。30ターンを超えると敗北です。</p><h3>探索と周回</h3><p>探索ではHPを次の階層へ引き継ぎます。休憩は2回、全員を40%回復。帰還で探索中の報酬を全額受け取り、敗北時はコインの75%と育成石を受け取ります。第10層クリアで自動帰還。</p><p>周回はクリア済みの階層を最大10回。毎戦HP全回復で開始し、報酬はその都度獲得します。時間回復スタミナはありません。</p></div>`,'help');}
function help(){openModal(`${modalHead('遊び方')}<div class="rules-copy"><h3>召喚</h3><p>地域を選んで仲間を獲得。1回300コイン、10回2,700コイン。</p><h3>仲間</h3><p>3体を編成。育成石でLv.30まで育成、同じ仲間を重ねて6突破まで強化できます。攻撃・守護・回復を1体ずつ組むとHP +15%。</p><h3>探索</h3><p>五行とスキルを使うターン制戦闘。体力を見て続行・休憩・帰還を選びます。クリア済みの場所は1・5・10回周回できます。</p><h3>スロット・報酬</h3><p>スロットでゲーム内コインをベット。ミッションと3戦ごとの報酬も受け取れます。</p><p>ゲーム内コインのみ。購入・換金はありません。</p><h3>保存</h3><p>このブラウザに自動保存します。旧版の所持コイン・獲得数・レベルは引き継ぎ済みです。別の端末やブラウザへの自動同期はありません。</p></div>`,'help');}
function settings(){const s=game.state,standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;openModal(`${modalHead('設定')}<div class="settings-links">${!standalone?`<button data-action="install-help">${icon('grid')}<span>ホーム画面に追加</span>${icon('chev')}</button>`:''}<button data-action="help">${icon('info')}<span>遊び方</span>${icon('chev')}</button></div><div class="settings-row"><div><strong>効果音</strong></div><input class="toggle" type="checkbox" data-setting="sound" aria-label="効果音" ${s.settings.sound?'checked':''}></div><div class="settings-row"><div><strong>アニメーション</strong><p>オフにすると召喚演出を省略します。</p></div><input class="toggle" type="checkbox" data-setting="motion" aria-label="アニメーション" ${s.settings.motion?'checked':''}></div><div class="settings-row"><div><strong>進行状況</strong><p>召喚 ${fmt(s.pulls)}回 / 戦闘 ${fmt(s.raids)}回<br>${game.storageAvailable?'このブラウザに保存しています。':'保存できません。タブを閉じると失われます。'}</p></div><button class="button secondary small" data-action="export">保存データを書き出す</button></div><div class="settings-row"><div><strong>保存データを読み込む</strong><p>別の端末・公開先から進行状況を移せます。</p></div><button class="button secondary small" data-action="import">ファイルを選択</button></div><div class="settings-row"><div><strong>最初から始める</strong><p>所持コイン・仲間・進行状況を初期化します。</p></div><button class="button danger" data-action="reset-confirm">初期化</button></div>`,'settings');}
function slotHelp(){openModal(`${modalHead('スロットのルール')}<div class="rules-copy"><p>ベットを先に支払い、3つのリールを回します。各リールは5絵柄を20%ずつ、独立に抽選します。</p></div><table class="rules-table"><thead><tr><th>結果</th><th>確率</th><th>払戻し</th></tr></thead><tbody>${SLOT_SYMBOLS.map(s=>`<tr><td>${s.name}が3つ</td><td>0.8%</td><td>${s.multiplier}倍</td></tr>`).join('')}<tr><td>2つだけ一致</td><td>48%</td><td>1倍（ベット返却）</td></tr><tr><td>すべて異なる</td><td>48%</td><td>0</td></tr></tbody></table><div class="rules-copy"><p>例：300コインで翡翠が3つなら払戻し3,000、収支 +2,700。2つ一致なら払戻し300、収支0です。</p><p>理論上の平均払戻率は100%。個別の結果や収支は保証されません。ゲーム内専用コインで、購入・換金はできません。</p></div>`,'slot-help');}
function summonResults(){if(!revealData)return;const {result,count}=revealData,n=result.results.filter(u=>u.new).length,stones=result.results.reduce((a,u)=>a+u.shards,0);openModal(`${modalHead('召喚結果')}<p class="modal-subtitle">新規 ${n}体 / 育成石 +${stones} / 重複 ${count-n}体</p><div class="result-grid ${count===1?'single':''}">${result.results.map((u,i)=>card(u,u,i)).join('')}</div><div class="result-summary"><p>UR確定まで ${60-game.state.pity}回<br>SSR以上確定まで ${20-game.state.highPity}回</p><div class="result-actions"><button class="button secondary" data-action="close-modal">戻る</button><button class="button gold" data-action="summon" data-count="${count}">${count}回召喚 · ${fmt(SUMMON_COST[count])}</button></div></div>`,'results');}
function finishReveal(){revealToken++;clearTimeout(revealTimer);busy=false;render();summonResults();}
async function summon(count){if(busy||farmJob)return;const r=game.summon(count,banner);if(!r.ok){toast(r.error);return;}busy=true;revealData={result:r,count};const token=++revealToken,high=[...r.results].sort((a,b)=>RARITIES[b.rarity].stars-RARITIES[a.rarity].stars)[0];sync();if(reduced()){finishReveal();return;}const color=high.rarity==='UR'?'#ba9758':high.rarity==='SSR'?'#b5a16c':'#a299b7';sound();openModal(`${modalHead('召喚')}<div class="summon-charge" style="--reveal:${color}"><button class="text-button skip-reveal" data-action="skip-reveal">スキップ ${icon('chev')}</button><i class="shooting-star"></i><i class="shooting-star"></i><div class="summon-ring">${icon(high.rarity==='UR'?'star':'flower')}</div><span class="charge-label">${r.results.some(x=>x.guaranteed==='UR')?'UR確定':r.results.some(x=>x.guaranteed==='SSR')?'SSR以上確定':''}</span></div>`,'charge');await sleep(850);if(token!==revealToken)return;busy=false;render();if(['SSR','UR'].includes(high.rarity)){openModal(`${modalHead('召喚')}<div class="rare-reveal ${high.rarity==='UR'?'ur':''}"><span class="rare-grade">${high.rarity}</span>${high.guaranteed?'<span class="guarantee-badge">確定召喚</span>':''}<img src="${high.art}" alt="${high.name}"><h3>${high.name}</h3>${stars(high.rarity)}<button class="button secondary" data-action="reveal-results">結果を見る</button></div>`,'rare');sound(high.rarity==='UR'?'ur':'rare');confetti(true);revealTimer=setTimeout(()=>{if(activeModal==='rare'&&token===revealToken)summonResults();},1800);}else{summonResults();sound('win');}}
function stopAuto(){autoBattle=false;clearTimeout(autoTimer);autoTimer=null;}
async function battleAction(action=null){if(busy)return;const r=action?game.act(action):game.autoAction();if(!r.ok){stopAuto();toast(r.error);return;}busy=true;damageDisplay=r.events.find(e=>e.target==='enemy')||null;sound('hit');render();await sleep(reduced()?80:350);damageDisplay=null;busy=false;if(r.status!=='active'){stopAuto();if(r.status==='victory'){sound('win');confetti();}else sound('lose');}render();if(autoBattle&&page==='raid'&&game.state.battle?.status==='active')autoTimer=setTimeout(()=>battleAction(),reduced()?90:400);}
function stopFarm(show=true){clearTimeout(farmTimer);farmTimer=null;if(farmJob){const {done,coins,shards}=farmJob;farmJob=null;if(show)toast(`${done}回周回 · +${fmt(coins)}コイン / +${shards}育成石`);}}
function farmStep(){if(!farmJob||page!=='raid')return;const r=game.farm(farmJob.region,farmJob.floor);if(!r.ok){stopFarm(false);toast(r.error);render();return;}farmJob.done++;farmJob.coins+=r.coins;farmJob.shards+=r.shards;sync();render();if(farmJob.done>=farmJob.total){stopFarm();render();sound('win');}else farmTimer=setTimeout(farmStep,reduced()?160:600);}
async function spin(){if(busy||farmJob)return;const result=game.spin(bet);if(!result.ok){toast(result.error);return;}busy=true;slotResult=null;sync();render();const seq=[1,3,0,4,2];let frame=0;const interval=setInterval(()=>{if(page!=='arcade')return;for(let i=0;i<3;i++){const reel=$('#reel-'+i);if(reel?.classList.contains('spinning')){const idx=seq[(frame+i)%5];$('img',reel).src=SLOT_SYMBOLS[idx].art;}}frame++;},100);for(let i=0;i<3;i++)$('#reel-'+i)?.classList.add('spinning');sound();try{for(let i=0;i<3;i++){await sleep(reduced()?35:i===0?450:250);if(page==='arcade'){const el=$('#reel-'+i);if(el){el.classList.remove('spinning');$('img',el).src=SLOT_SYMBOLS[result.reels[i]].art;$('img',el).alt=SLOT_SYMBOLS[result.reels[i]].name;}}}slotResult=result;}finally{clearInterval(interval);busy=false;render();}if(result.multiplier>1){sound('win');confetti(result.multiplier>=10);}else sound(result.multiplier===0?'lose':'click');}
function check(result,message){if(!result.ok){toast(result.error);return false;}render();if(message)toast(message);sound();return true;}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;switch(action){
 case'daily':dailyBonus();break;
 case'login':{const r=game.claimLogin();if(r.ok){render();if(activeModal==='daily')dailyBonus();toast(`${fmt(r.coins)}コイン / ${r.shards}育成石を受け取りました。`);sound('win');confetti();}else toast(r.error);}break;
 case'favorites':favorites();break;
 case'favorite':if(check(game.setFavorite(id))){closeModal();}break;
 case'pet':touchFavorite();break;
 case'install-help':installHelp();break;
 case'banner':banner=el.dataset.region;render();break;
 case'view-region':collectionRegion=el.dataset.region;rarity='ALL';element='ALL';guardianOnly=false;ownedOnly=false;location.hash='collection';break;
 case'go-banner':banner=el.dataset.region;closeModal();location.hash='summon';render();break;
 case'summon':await summon(Number(el.dataset.count));break;
 case'skip-reveal':case'reveal-results':finishReveal();break;
 case'unit':showUnit(id);break;
 case'rates':ratesModal();break;
 case'close-modal':closeModal();break;
 case'settings':settings();break;
 case'sound':game.setSetting('sound',!game.state.settings.sound);sync();sound();break;
 case'help':help();break;
 case'combat-help':combatHelp();break;
 case'slot-help':slotHelp();break;
 case'rarity':rarity=el.dataset.value;render();break;
 case'element':element=el.dataset.value;render();break;
 case'equip-best':if(farmJob){toast('周回を停止してから編成できます。');break;}check(game.equipBest(),'役割を優先して編成しました。');break;
 case'move':if(farmJob){toast('周回を停止してください。');break;}check(game.move(id));break;
 case'equip':if(farmJob){toast('周回を停止してください。');break;}if(check(game.equip(id,el.dataset.slot===undefined?null:Number(el.dataset.slot))))showUnit(id);break;
 case'level':if(farmJob){toast('周回を停止してください。');break;}if(check(game.levelUp(id))){showUnit(id);toast('Lv.'+game.state.collection[id].level+'に育成しました。');}break;
 case'breakthrough':if(farmJob){toast('周回を停止してください。');break;}if(check(game.breakthrough(id))){showUnit(id);toast(game.state.collection[id].breakthrough+'突破。');sound('rare');confetti();}break;
 case'explore-region':if(farmJob)stopFarm();region=el.dataset.region;floor=1;render();break;
 case'floor':floor=Number(el.dataset.floor);render();break;
 case'start-explore':if(busy||farmJob)break;check(game.startExpedition(region,floor));break;
 case'continue':case'rest':if(busy)break;check(game.continueExpedition(action==='rest'));break;
 case'battle-act':if(!autoBattle)await battleAction(el.dataset.value);break;
 case'auto-battle':if(autoBattle){stopAuto();render();}else if(!busy){autoBattle=true;await battleAction();}break;
 case'return-confirm':stopAuto();openModal(`${modalHead('帰還しますか？')}<p class="modal-subtitle">クリア済みの報酬を全額受け取ります。進行中の戦闘の報酬は得られません。</p><div class="result-actions"><button class="button secondary" data-action="close-modal">続ける</button><button class="button" data-action="return-home">帰還</button></div>`,'return');break;
 case'return-home':if(busy){toast('行動が終わるまでお待ちください。');break;}stopAuto();{const r=game.returnHome();if($('#modal').open)closeModal();check(r,`${fmt(r.coins)}コイン / ${r.shards}育成石を受け取りました。`);}break;
 case'dismiss-battle':game.dismissBattle();render();break;
 case'farm':if(busy||farmJob)break;{const count=Number($('#farm-count').value);if(![1,5,10].includes(count))break;farmJob={total:count,done:0,coins:0,shards:0,region,floor};farmStep();}break;
 case'stop-farm':stopFarm();render();break;
 case'bet':if(!busy){bet=Number(el.dataset.bet);render();}break;
 case'spin':await spin();break;
 case'claim':{const r=game.claimMission(id);if(check(r,r.ok?`${fmt(r.reward)}コインを受け取りました。`:null)){sound('win');confetti();}}break;
 case'raid-reward':check(game.claimRaidReward(),'300コインと育成石10個を受け取りました。');break;
 case'export':{const blob=new Blob([JSON.stringify({version:2,state:game.state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='neon-vault-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('保存データを書き出しました。');}break;
 case'import':if(!busy)$('#save-import').click();break;
 case'import-confirm':if(!busy&&pendingImport){stopAuto();stopFarm(false);const r=game.importSave(pendingImport);pendingImport=null;if(r.ok){closeModal();location.hash='home';render();toast('保存データを読み込みました。');}else toast(r.error);}break;
 case'reset-confirm':openModal(`${modalHead('進行状況を初期化しますか？')}<p class="modal-subtitle">所持コイン・仲間・育成・突破・探索記録が初期状態に戻ります。取り消せません。</p><div class="result-actions"><button class="button secondary" data-action="settings">キャンセル</button><button class="button danger" data-action="reset">初期化する</button></div>`,'reset');break;
 case'reset':if(busy){toast('演出が終わるまでお待ちください。');break;}stopAuto();stopFarm(false);game.reset();slotResult=null;revealData=null;rarity='ALL';element='ALL';ownedOnly=false;guardianOnly=false;collectionRegion='ALL';floor=1;closeModal();location.hash='home';render();toast('初期化しました。');break;
 }});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='owned-only'){ownedOnly=t.checked;render();}if(t.id==='guardian-only'){guardianOnly=t.checked;render();}if(t.id==='region-filter'){collectionRegion=t.value;render();}if(t.dataset.setting){game.setSetting(t.dataset.setting,t.checked);sync();if(t.dataset.setting==='sound')sound();}});
$('#modal').addEventListener('cancel',e=>{if(activeModal==='charge'){e.preventDefault();finishReveal();}else{clearTimeout(revealTimer);activeModal=null;}});
$('#modal').addEventListener('close',()=>{document.body.append($('#confetti'));});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',navigate);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopAuto();stopFarm(false);}else render();});
window.addEventListener('pagehide',()=>{stopAuto();stopFarm(false);});
navigate();

$('#save-import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000){toast('ファイルが大きすぎます。');return;}const raw=await file.text(),r=game.previewImport(raw);if(!r.ok){toast(r.error);return;}pendingImport=raw;openModal(`${modalHead('保存データを読み込みますか？')}<p class="modal-subtitle">${fmt(r.state.coins)}コイン / 仲間 ${Object.keys(r.state.collection).length}種類 / 召喚 ${r.state.pulls}回<br>現在の進行状況をこのデータで置き換えます。</p><div class="result-actions"><button class="button secondary" data-action="close-modal">キャンセル</button><button class="button" data-action="import-confirm">読み込む</button></div>`,'import');});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
